```turtle
@prefix ea:   <http://example.org/onto/assessment#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .

<http://example.org/onto/assessment> a owl:Ontology ;
  rdfs:label "Educational Assessment Ontology" .

#################################################################
# TOP LEVEL: Assessment / Test / Examination
#################################################################

ea:Assessment a owl:Class ;
  rdfs:label "Assessment" ;
  skos:altLabel "educational evaluation" ;
  rdfs:comment "The systematic process of documenting and using empirical data on knowledge, skill, attitudes, aptitude and beliefs to refine programs and improve student learning. Assessment is often used interchangeably with 'test' but is not limited to tests." .

ea:Test a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:label "Test" ;
  rdfs:comment "A test is a form of assessment; assessment is not limited to tests." .

ea:Examination a owl:Class ;
  owl:equivalentClass ea:Test ;
  skos:altLabel "exam" ;
  rdfs:comment "'An examination (exam or evaluation), or test, is an educational assessment...' Note: the corpus also uses 'evaluation' as a synonym of the top-level term Assessment (educational evaluation) elsewhere; this terminological overlap is noted as a tension." .

ea:TestTaker a owl:Class ; rdfs:label "TestTaker" .
ea:Candidate a owl:Class ; owl:equivalentClass ea:TestTaker .
ea:Examiner a owl:Class ; rdfs:comment "The person who decides how well the student performed." .

#################################################################
# GRANULARITY (informal, no strict axis reified - narrative only)
#################################################################

ea:GranularityLevel a owl:Class ;
  rdfs:comment "Assessment can focus on the individual learner, learning community, course, program, institution, or educational system (granularity)." .
ea:LearnerGranularity rdfs:subClassOf ea:GranularityLevel .
ea:LearningCommunityGranularity rdfs:subClassOf ea:GranularityLevel .
ea:CourseGranularity rdfs:subClassOf ea:GranularityLevel .
ea:ProgramGranularity rdfs:subClassOf ea:GranularityLevel .
ea:InstitutionGranularity rdfs:subClassOf ea:GranularityLevel .
ea:EducationalSystemGranularity rdfs:subClassOf ea:GranularityLevel .
ea:GranularityLevel owl:disjointUnionOf
  ( ea:LearnerGranularity ea:LearningCommunityGranularity ea:CourseGranularity
    ea:ProgramGranularity ea:InstitutionGranularity ea:EducationalSystemGranularity ) .
ea:hasGranularity a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:GranularityLevel .

#################################################################
# AXIS 1: PURPOSE (placement / formative / summative / diagnostic)
#################################################################

ea:hasPurposeCategory a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:PurposeCategory .

ea:PurposeCategory a owl:Class ;
  rdfs:comment "Coordinate categorization: 'Placement, formative, summative and diagnostic assessment'. Elsewhere the corpus states assessment 'is often divided into initial, formative, and summative categories' (a 3-way division), then separately numbers diagnostic as a 4th. Both groupings are modeled." .
ea:PlacementPurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:FormativePurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:SummativePurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:DiagnosticPurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:PurposeCategory owl:disjointUnionOf
  ( ea:PlacementPurpose ea:FormativePurpose ea:SummativePurpose ea:DiagnosticPurpose ) .

ea:PlacementAssessment a owl:Class ;
  skos:altLabel "pre-assessment", "initial assessment", "threshold knowledge test" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasPurposeCategory ;
      owl:someValuesFrom ea:PlacementPurpose ] ) ] ;
  rdfs:comment "Used to place students according to prior achievement or characteristics at the appropriate point in an instructional sequence; conducted before instruction to establish a baseline." .

ea:FormativeAssessment a owl:Class ;
  skos:altLabel "educative assessment", "assessment for learning", "classroom assessment", "formative evaluation", "formative feedback" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasPurposeCategory ;
      owl:someValuesFrom ea:FormativePurpose ] ) ] ;
  rdfs:comment "Generally carried out throughout a course; used to help learning, not necessarily graded." .

ea:SummativeAssessment a owl:Class ;
  skos:altLabel "assessment of learning", "summative evaluation" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasPurposeCategory ;
      owl:someValuesFrom ea:SummativePurpose ] ) ] ;
  rdfs:comment "Generally carried out at the end of a course or project; typically graded." .

ea:DiagnosticAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasPurposeCategory ;
      owl:someValuesFrom ea:DiagnosticPurpose ] ) ] ;
  rdfs:subClassOf ea:FormativeAssessment ;
  rdfs:comment "TENSION: one passage lists Diagnostic as a coordinate 4th category alongside Placement/Formative/Summative (hence it is given its own disjoint PurposeCategory value above), while another passage states 'A common form of formative assessment is diagnostic assessment', here modeled as rdfs:subClassOf ea:FormativeAssessment. Because hasPurposeCategory is functional and FormativePurpose/DiagnosticPurpose are asserted disjoint, these two claims jointly render DiagnosticAssessment logically unsatisfiable under strict OWL semantics -- this contradiction is preserved intentionally to reflect the corpus disagreement rather than silently resolved." .

ea:SelfAssessment a owl:Class ; rdfs:subClassOf ea:DiagnosticAssessment ;
  rdfs:comment "Self-assessment is a form of diagnostic assessment in which students assess themselves." .

ea:ForwardLookingAssessment a owl:Class ; rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Asks those being assessed to consider themselves in hypothetical future situations." .

#################################################################
# AXIS 2: OBJECTIVITY (objective / subjective)
#################################################################

ea:hasObjectivityCategory a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:ObjectivityCategory .
ea:ObjectivityCategory a owl:Class .
ea:ObjectiveValue a owl:Class ; rdfs:subClassOf ea:ObjectivityCategory .
ea:SubjectiveValue a owl:Class ; rdfs:subClassOf ea:ObjectivityCategory .
ea:ObjectivityCategory owl:disjointUnionOf ( ea:ObjectiveValue ea:SubjectiveValue ) .

ea:ObjectiveAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasObjectivityCategory ;
      owl:someValuesFrom ea:ObjectiveValue ] ) ] ;
  rdfs:comment "A form of questioning that has a single correct answer." .

ea:SubjectiveAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasObjectivityCategory ;
      owl:someValuesFrom ea:SubjectiveValue ] ) ] ;
  rdfs:comment "A form of questioning that may have more than one correct answer." .

#################################################################
# AXIS 3: REFERENCING (criterion / norm / ipsative)
#################################################################

ea:hasReferencingCategory a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:ReferencingCategory .
ea:ReferencingCategory a owl:Class .
ea:CriterionReferencingValue a owl:Class ; rdfs:subClassOf ea:ReferencingCategory .
ea:NormReferencingValue a owl:Class ; rdfs:subClassOf ea:ReferencingCategory .
ea:IpsativeReferencingValue a owl:Class ; rdfs:subClassOf ea:ReferencingCategory .
ea:ReferencingCategory owl:disjointUnionOf
  ( ea:CriterionReferencingValue ea:NormReferencingValue ea:IpsativeReferencingValue ) .

ea:CriterionReferencedAssessment a owl:Class ;
  skos:altLabel "standards-based assessment" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasReferencingCategory ;
      owl:someValuesFrom ea:CriterionReferencingValue ] ) ] ;
  rdfs:comment "Candidates are measured against defined, objective criteria, e.g. a driving test." .

ea:NormReferencedAssessment a owl:Class ;
  skos:altLabel "normative assessment", "grading on the curve" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasReferencingCategory ;
      owl:someValuesFrom ea:NormReferencingValue ] ) ] ;
  rdfs:comment "Relative to the student body taking it; compares students, e.g. IQ test." .

ea:IpsativeAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasReferencingCategory ;
      owl:someValuesFrom ea:IpsativeReferencingValue ] ) ] ;
  rdfs:comment "Self-comparison either in the same domain over time, or across domains within the same student." .

ea:NormReferencedTest a owl:Class ;
  skos:altLabel "NRT" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
    [ a owl:Restriction ; owl:onProperty ea:hasReferencingCategory ;
      owl:someValuesFrom ea:NormReferencingValue ] ) ] .
ea:CriterionReferencedTest a owl:Class ;
  skos:altLabel "CRT" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
    [ a owl:Restriction ; owl:onProperty ea:hasReferencingCategory ;
      owl:someValuesFrom ea:CriterionReferencingValue ] ) ] .

ea:StandardsReferencedAssessment a owl:Class ;
  owl:equivalentClass ea:CriterionReferencedAssessment ;
  rdfs:comment "'Criterion-referenced tests have also been called standards-based assessments'." .

ea:MasteryTest a owl:Class ; rdfs:subClassOf ea:CriterionReferencedTest ;
  rdfs:comment "A criterion-referenced test that involves a cutscore." .
ea:hasCutScore a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain ea:CriterionReferencedTest ; rdfs:range xsd:decimal .
ea:hasPercentileRank a owl:DatatypeProperty ;
  rdfs:domain ea:NormReferencedTest ; rdfs:range xsd:decimal .

ea:CompetitiveExamination a owl:Class ;
  rdfs:subClassOf ea:NormReferencedTest ;
  rdfs:comment "Competitive exams are norm-referenced, high-stakes tests in which candidates are ranked." .

#################################################################
# AXIS 4: FORMALITY (formal / informal)
#################################################################

ea:hasFormalityCategory a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:FormalityCategory .
ea:FormalityCategory a owl:Class .
ea:FormalValue a owl:Class ; rdfs:subClassOf ea:FormalityCategory .
ea:InformalValue a owl:Class ; rdfs:subClassOf ea:FormalityCategory .
ea:FormalityCategory owl:disjointUnionOf ( ea:FormalValue ea:InformalValue ) .

ea:FormalAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasFormalityCategory ;
      owl:someValuesFrom ea:FormalValue ] ) ] ;
  rdfs:comment "Usually implies a written document, given a numerical score or grade." .

ea:InformalAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasFormalityCategory ;
      owl:someValuesFrom ea:InformalValue ] ) ] ;
  rdfs:comment "Occurs more casually; does not contribute to a student's final grade." .

#################################################################
# AXIS 5: ADMINISTRATION ORIGIN (internal / external)
#################################################################

ea:hasAdministrationCategory a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:AdministrationCategory .
ea:AdministrationCategory a owl:Class .
ea:InternalValue a owl:Class ; rdfs:subClassOf ea:AdministrationCategory .
ea:ExternalValue a owl:Class ; rdfs:subClassOf ea:AdministrationCategory .
ea:AdministrationCategory owl:disjointUnionOf ( ea:InternalValue ea:ExternalValue ) .

ea:InternalAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasAdministrationCategory ;
      owl:someValuesFrom ea:InternalValue ] ) ] ;
  rdfs:comment "Set and marked by the school (teachers)." .

ea:ExternalAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasAdministrationCategory ;
      owl:someValuesFrom ea:ExternalValue ] ) ] ;
  rdfs:comment "Set by the governing body and marked by unbiased personnel." .

#################################################################
# AXIS 6: STANDARDIZATION (on Test)
#################################################################

ea:hasStandardizationCategory a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Test ; rdfs:range ea:StandardizationCategory .
ea:StandardizationCategory a owl:Class .
ea:StandardizedValue a owl:Class ; rdfs:subClassOf ea:StandardizationCategory .
ea:NonStandardizedValue a owl:Class ; rdfs:subClassOf ea:StandardizationCategory .
ea:StandardizationCategory owl:disjointUnionOf ( ea:StandardizedValue ea:NonStandardizedValue ) .

ea:StandardizedTest a owl:Class ;
  skos:altLabel "standardized assessment" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
    [ a owl:Restriction ; owl:onProperty ea:hasStandardizationCategory ;
      owl:someValuesFrom ea:StandardizedValue ] ) ] ;
  rdfs:comment "Administered and scored in a consistent or standard manner for all test takers." .

ea:NonStandardizedTest a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
    [ a owl:Restriction ; owl:onProperty ea:hasStandardizationCategory ;
      owl:someValuesFrom ea:NonStandardizedValue ] ) ] ;
  rdfs:comment "Significantly different tests given to different test takers, or evaluated differently." .

ea:hasAccommodation a owl:ObjectProperty ; rdfs:domain ea:StandardizedTest ; rdfs:range ea:TestAccommodation .
ea:TestAccommodation a owl:Class ;
  rdfs:comment "Changing testing conditions to improve fairness without undermining the test's purpose." .
ea:TestModification a owl:Class ;
  rdfs:comment "If an accommodation undermines the purpose of the test it becomes a modification, no longer standardized." .

#################################################################
# AXIS 7: STAKES (on Test)
#################################################################

ea:hasStakesCategory a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Test ; rdfs:range ea:StakesCategory .
ea:StakesCategory a owl:Class .
ea:HighStakesValue a owl:Class ; rdfs:subClassOf ea:StakesCategory .
ea:LowStakesValue a owl:Class ; rdfs:subClassOf ea:StakesCategory .
ea:StakesCategory owl:disjointUnionOf ( ea:HighStakesValue ea:LowStakesValue ) .

ea:HighStakesTest a owl:Class ;
  skos:altLabel "high-stakes assessment" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
    [ a owl:Restriction ; owl:onProperty ea:hasStakesCategory ;
      owl:someValuesFrom ea:HighStakesValue ] ) ] ;
  rdfs:comment "A test with a desired reward for good performance; important consequences for the test taker." .

ea:LowStakesTest a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
    [ a owl:Restriction ; owl:onProperty ea:hasStakesCategory ;
      owl:someValuesFrom ea:LowStakesValue ] ) ] .

ea:CompetitiveExamination rdfs:subClassOf ea:HighStakesTest .

#################################################################
# AXIS 8: MODALITY (written / oral / practical) on Test
#################################################################

ea:hasModalityCategory a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Test ; rdfs:range ea:ModalityCategory .
ea:ModalityCategory a owl:Class .
ea:WrittenValue a owl:Class ; rdfs:subClassOf ea:ModalityCategory .
ea:OralValue a owl:Class ; rdfs:subClassOf ea:ModalityCategory .
ea:PracticalValue a owl:Class ; rdfs:subClassOf ea:ModalityCategory .
ea:ModalityCategory owl:disjointUnionOf ( ea:WrittenValue ea:OralValue ea:PracticalValue ) .

ea:WrittenTest a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
    [ a owl:Restriction ; owl:onProperty ea:hasModalityCategory ;
      owl:someValuesFrom ea:WrittenValue ] ) ] ;
  rdfs:comment "Administered on paper or computer." .

ea:OralTest a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
    [ a owl:Restriction ; owl:onProperty ea:hasModalityCategory ;
      owl:someValuesFrom ea:OralValue ] ) ] .

ea:PerformanceTest a owl:Class ;
  skos:altLabel "practical test" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
    [ a owl:Restriction ; owl:onProperty ea:hasModalityCategory ;
      owl:someValuesFrom ea:PracticalValue ] ) ] ;
  rdfs:comment "Requires an examinee to actually perform a task or activity rather than answering questions, e.g. a behind-the-wheel driving test." .

ea:WorkSample a owl:Class ; rdfs:subClassOf ea:PerformanceTest ;
  rdfs:comment "Performance test used for personnel selection." .
ea:SimulationTest a owl:Class ; rdfs:subClassOf ea:PerformanceTest .

#################################################################
# Standalone assessment kinds (performance-based, authentic, complex, continuous)
#################################################################

ea:PerformanceBasedAssessment a owl:Class ; rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Requires students to solve real-world problems or produce something with real-world application; similar to summative assessment in focusing on achievement. 'Performance assessments may also be called authentic assessments.'" .

ea:hasPerformanceFormatCategory a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:PerformanceBasedAssessment ; rdfs:range ea:PerformanceFormatCategory .
ea:PerformanceFormatCategory a owl:Class .
ea:ProductFormatValue a owl:Class ; rdfs:subClassOf ea:PerformanceFormatCategory .
ea:ActionFormatValue a owl:Class ; rdfs:subClassOf ea:PerformanceFormatCategory .
ea:PerformanceFormatCategory owl:disjointUnionOf ( ea:ProductFormatValue ea:ActionFormatValue ) .

ea:ProductBasedPerformance a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:PerformanceBasedAssessment
    [ a owl:Restriction ; owl:onProperty ea:hasPerformanceFormatCategory ;
      owl:someValuesFrom ea:ProductFormatValue ] ) ] ;
  rdfs:comment "Results in a product such as a painting, portfolio, paper, or exhibition." .

ea:ActionBasedPerformance a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:PerformanceBasedAssessment
    [ a owl:Restriction ; owl:onProperty ea:hasPerformanceFormatCategory ;
      owl:someValuesFrom ea:ActionFormatValue ] ) ] ;
  rdfs:comment "Consists of a performance such as a speech, athletic skill, musical recital, or reading." .

ea:AuthenticAssessment a owl:Class ; rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Measurement of accomplishments within a realistic, practical context relevant outside the school setting. Noted by the corpus as sometimes used synonymously with Performance-based assessment." .

ea:ComplexAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasRubric ; owl:someValuesFrom ea:Rubric ] ) ] ;
  rdfs:comment "Requires a rubric and an expert examiner, e.g. thesis, funding proposal." .

ea:ContinuousAssessment a owl:Class ; rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Evaluates a student's progress throughout a prescribed course; an alternative to the final examination system. Often includes some form of formative assessment." .
ea:hasComponent a owl:ObjectProperty ; rdfs:domain ea:Assessment ; rdfs:range ea:Assessment .
ea:isComponentOf a owl:ObjectProperty ; owl:inverseOf ea:hasComponent .
ea:ContinuousAssessment rdfs:subClassOf
  [ a owl:Restriction ; owl:onProperty ea:hasComponent ; owl:someValuesFrom ea:FormativeAssessment ] .

ea:CommonAssessment a owl:Class ; rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Used in a school or district to ensure teachers evaluate performance in a consistent, reliable way." .
ea:InterimAssessment a owl:Class ; rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Used to evaluate learning progress toward future summative assessments. TENSION: 'Some educators consider interim tests to be formative... but others may consider them to be summative'; not committed to either subclass here." .
ea:ScreeningAssessment a owl:Class ; rdfs:subClassOf ea:Assessment .
ea:PortfolioBasedAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasPortfolio ; owl:someValuesFrom ea:Portfolio ] ) ] .

#################################################################
# QUIZ / MIDTERM / FINAL EXAM
#################################################################

ea:Quiz a owl:Class ; rdfs:subClassOf ea:Examination, ea:FormativeAssessment ;
  rdfs:comment "A brief assessment covering a small amount of material; usually provided as formative assessment." .
ea:MidtermExam a owl:Class ; rdfs:subClassOf ea:Examination ;
  rdfs:subClassOf [ a owl:Class ; owl:unionOf ( ea:FormativeAssessment ea:SummativeAssessment ) ] ;
  rdfs:comment "An exam given near the middle of a grading term; 'a type of formative or summative assessment.'" .
ea:FinalExam a owl:Class ; rdfs:subClassOf ea:Examination, ea:SummativeAssessment .

#################################################################
# TEST ITEMS / QUESTION FORMATS
#################################################################

ea:TestItem a owl:Class ;
  rdfs:comment "Colloquially called a 'question', but items need not be phrased as questions." .
ea:hasTestItem a owl:ObjectProperty ; rdfs:domain ea:Test ; rdfs:range ea:TestItem .
ea:isItemOf a owl:ObjectProperty ; owl:inverseOf ea:hasTestItem .
ea:hasItemCount a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Test ; rdfs:range xsd:integer .

ea:ObjectiveItem a owl:Class ; rdfs:subClassOf ea:TestItem .
ea:SubjectiveItem a owl:Class ; rdfs:subClassOf ea:TestItem .
owl:AllDisjointClasses [ owl:members ( ea:ObjectiveItem ea:SubjectiveItem ) ] .

ea:AnswerOption a owl:Class .
ea:hasStem a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain ea:MultipleChoiceItem ; rdfs:range xsd:string .
ea:hasOption a owl:ObjectProperty ; rdfs:domain ea:MultipleChoiceItem ; rdfs:range ea:AnswerOption .
ea:hasKey a owl:ObjectProperty ; rdfs:subPropertyOf ea:hasOption ;
  rdfs:domain ea:MultipleChoiceItem ; rdfs:range ea:AnswerOption .
ea:hasDistractor a owl:ObjectProperty ; rdfs:subPropertyOf ea:hasOption ;
  rdfs:domain ea:MultipleChoiceItem ; rdfs:range ea:AnswerOption .

ea:MultipleChoiceItem a owl:Class ;
  skos:altLabel "MCQ" ;
  rdfs:subClassOf ea:ObjectiveItem ;
  rdfs:subClassOf [ a owl:Restriction ; owl:onProperty ea:hasKey ; owl:cardinality 1 ] ;
  rdfs:comment "Consists of a stem and alternative answers; only one answer may be keyed correct (contrast MultipleResponseItem)." .

ea:MultipleResponseItem a owl:Class ;
  rdfs:subClassOf ea:ObjectiveItem ;
  rdfs:subClassOf [ a owl:Restriction ; owl:onProperty ea:hasKey ; owl:minCardinality 2 ] ;
  rdfs:comment "More than one answer may be keyed as correct." .
owl:AllDisjointClasses [ owl:members ( ea:MultipleChoiceItem ea:MultipleResponseItem ) ] .

ea:TrueFalseItem a owl:Class ; rdfs:subClassOf ea:ObjectiveItem .
ea:MatchingItem a owl:Class ; rdfs:subClassOf ea:ObjectiveItem .
ea:FillInTheBlankItem a owl:Class ; rdfs:subClassOf ea:ObjectiveItem ;
  rdfs:comment "Requires the test taker to recall the correct term; may or may not supply a word bank." .
ea:ExtendedResponseItem a owl:Class ; rdfs:subClassOf ea:SubjectiveItem .
ea:EssayItem a owl:Class ; rdfs:subClassOf ea:SubjectiveItem, ea:ExtendedResponseItem ;
  skos:altLabel "free response question", "FRQ", "essay question" .
ea:ShortAnswerItem a owl:Class ; rdfs:subClassOf ea:SubjectiveItem .

ea:TrueFalseFamilyItem a owl:Class ; rdfs:subClassOf ea:MultipleChoiceItem ;
  rdfs:comment "First family of multiple-choice items: requires choosing all appropriate answers. Note naming overlap with the standalone ea:TrueFalseItem concept used elsewhere in the corpus." .
ea:OneBestAnswerItem a owl:Class ; rdfs:subClassOf ea:MultipleChoiceItem ;
  rdfs:comment "Second family: requires answering only one from a list of answers." .
owl:AllDisjointClasses [ owl:members ( ea:TrueFalseFamilyItem ea:OneBestAnswerItem ) ] .

#################################################################
# RUBRICS
#################################################################

ea:Rubric a owl:Class ;
  rdfs:comment "A scoring guide used to evaluate the quality of students' constructed responses." .
ea:hasRubric a owl:ObjectProperty ; rdfs:domain ea:Assessment ; rdfs:range ea:Rubric .
ea:isRubricOf a owl:ObjectProperty ; owl:inverseOf ea:hasRubric .

ea:HolisticRubric a owl:Class ; rdfs:subClassOf ea:Rubric ;
  rdfs:comment "Provides an overall rating for a piece of work, considering all aspects." .
ea:AnalyticRubric a owl:Class ; rdfs:subClassOf ea:Rubric ;
  rdfs:comment "Evaluates various dimensions or components separately." .
ea:DevelopmentalRubric a owl:Class ;
  rdfs:subClassOf ea:AnalyticRubric ;
  rdfs:comment "'A subset of analytical rubrics'. TENSION: the corpus first lists holistic/analytic/developmental as three coordinate rubric kinds ('Rubrics can be classified as holistic, analytic, or developmental'), then immediately subordinates developmental under analytic. Both claims are encoded: DevelopmentalRubric is asserted rdfs:subClassOf ea:AnalyticRubric, while all three remain distinguished named classes." .
owl:AllDisjointClasses [ owl:members ( ea:HolisticRubric ea:AnalyticRubric ) ] .

#################################################################
# SCORING / GRADING METHODS
#################################################################

ea:ScoringMethod a owl:Class .
ea:HolisticGrading a owl:Class ; rdfs:subClassOf ea:ScoringMethod ;
  skos:altLabel "holistic scoring", "nonreductionist grading" ;
  rdfs:comment "Bases a grade on a paper's overall quality, treating the composition as a whole." .
ea:AnalyticGrading a owl:Class ; rdfs:subClassOf ea:ScoringMethod ;
  rdfs:comment "Takes more factors into account when assigning a grade; criterion-by-criterion judgments." .
owl:AllDisjointClasses [ owl:members ( ea:HolisticGrading ea:AnalyticGrading ) ] .
ea:TraitInformedScoring a owl:Class ; rdfs:subClassOf ea:HolisticGrading ;
  rdfs:comment "Trains raters to score to a scoring guide; 'comes close to analytic scoring methods' but 'remains holistic at heart', hence modeled under HolisticGrading." .

#################################################################
# VALIDITY
#################################################################

ea:Validity a owl:Class ;
  rdfs:comment "The degree to which a measurement tool measures what it claims to measure." .
ea:hasValidity a owl:ObjectProperty ; rdfs:domain ea:Assessment ; rdfs:range ea:Validity .
ea:hasCorrelationCoefficient a owl:DatatypeProperty ; rdfs:domain ea:Validity ; rdfs:range xsd:decimal .

ea:ContentValidity a owl:Class ; rdfs:subClassOf ea:Validity ; skos:altLabel "logical validity" .
ea:CriterionValidity a owl:Class ; rdfs:subClassOf ea:Validity ; skos:altLabel "criterion-related validity" .
ea:ConstructValidity a owl:Class ; rdfs:subClassOf ea:Validity .
ea:ConsequentialValidity a owl:Class ; rdfs:subClassOf ea:Validity .
ea:FaceValidity a owl:Class ; rdfs:subClassOf ea:Validity .

ea:ContentValidity rdfs:subClassOf ea:ConstructValidity .
ea:CriterionValidity rdfs:subClassOf ea:ConstructValidity .
ea:FaceValidity rdfs:subClassOf ea:ConstructValidity .
ea:ConstructValidity rdfs:comment "TENSION: one passage lists Content/Criterion/Construct validity (plus Consequential/Face) as coordinate categories of evidence; another states 'Construct validity... subsumes all other types of validity' / 'construct validity as the overarching concern of validity research, subsuming all other types of validity evidence such as content validity and criterion validity'. Both the coordinate listing (siblings under ea:Validity) and the subsumption (rdfs:subClassOf ea:ConstructValidity) are asserted." .

ea:ConvergentValidity a owl:Class ; rdfs:subClassOf ea:ConstructValidity .
ea:DiscriminantValidity a owl:Class ; rdfs:subClassOf ea:ConstructValidity ;
  skos:altLabel "divergent validity" .
ea:ConvergentValidity owl:disjointWith ea:DiscriminantValidity .

ea:hasTimingCategory a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:CriterionValidity ; rdfs:range ea:TimingCategory .
ea:TimingCategory a owl:Class .
ea:ConcurrentTimingValue a owl:Class ; rdfs:subClassOf ea:TimingCategory .
ea:PredictiveTimingValue a owl:Class ; rdfs:subClassOf ea:TimingCategory .
ea:TimingCategory owl:disjointUnionOf ( ea:ConcurrentTimingValue ea:PredictiveTimingValue ) .

ea:ConcurrentValidity a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:CriterionValidity
    [ a owl:Restriction ; owl:onProperty ea:hasTimingCategory ;
      owl:someValuesFrom ea:ConcurrentTimingValue ] ) ] ;
  rdfs:comment "Test data and criterion data collected at the same time." .
ea:PredictiveValidity a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:CriterionValidity
    [ a owl:Restriction ; owl:onProperty ea:hasTimingCategory ;
      owl:someValuesFrom ea:PredictiveTimingValue ] ) ] ;
  rdfs:comment "Test data collected first, to predict criterion data collected later." .

#################################################################
# RELIABILITY
#################################################################

ea:Reliability a owl:Class ;
  rdfs:comment "The consistency of an assessment: freedom of a measure from measurement error." .
ea:hasReliability a owl:ObjectProperty ; rdfs:domain ea:Assessment ; rdfs:range ea:Reliability .
ea:hasReliabilityCoefficient a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Reliability ; rdfs:range xsd:decimal .
ea:hasTrueScoreVariance a owl:DatatypeProperty ; rdfs:domain ea:Reliability ; rdfs:range xsd:decimal .
ea:hasErrorVariance a owl:DatatypeProperty ; rdfs:domain ea:Reliability ; rdfs:range xsd:decimal .
ea:hasObservedScoreVariance a owl:DatatypeProperty ; rdfs:domain ea:Reliability ; rdfs:range xsd:decimal .

# Classification A: by source of error ("There are four types of reliability")
ea:hasErrorSourceCategory a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Reliability ; rdfs:range ea:ErrorSourceCategory .
ea:ErrorSourceCategory a owl:Class .
ea:StudentErrorSourceValue a owl:Class ; rdfs:subClassOf ea:ErrorSourceCategory .
ea:RaterErrorSourceValue a owl:Class ; rdfs:subClassOf ea:ErrorSourceCategory .
ea:TestAdministrationErrorSourceValue a owl:Class ; rdfs:subClassOf ea:ErrorSourceCategory .
ea:TestErrorSourceValue a owl:Class ; rdfs:subClassOf ea:ErrorSourceCategory .
ea:ErrorSourceCategory owl:disjointUnionOf
  ( ea:StudentErrorSourceValue ea:RaterErrorSourceValue
    ea:TestAdministrationErrorSourceValue ea:TestErrorSourceValue ) .

ea:StudentRelatedReliability a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Reliability
    [ a owl:Restriction ; owl:onProperty ea:hasErrorSourceCategory ;
      owl:someValuesFrom ea:StudentErrorSourceValue ] ) ] .
ea:RaterRelatedReliability a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Reliability
    [ a owl:Restriction ; owl:onProperty ea:hasErrorSourceCategory ;
      owl:someValuesFrom ea:RaterErrorSourceValue ] ) ] .
ea:TestAdministrationRelatedReliability a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Reliability
    [ a owl:Restriction ; owl:onProperty ea:hasErrorSourceCategory ;
      owl:someValuesFrom ea:TestAdministrationErrorSourceValue ] ) ] .
ea:TestRelatedReliability a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Reliability
    [ a owl:Restriction ; owl:onProperty ea:hasErrorSourceCategory ;
      owl:someValuesFrom ea:TestErrorSourceValue ] ) ] .

# Classification B: by estimation method ("several general classes of reliability estimates")
ea:hasEstimationMethodCategory a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Reliability ; rdfs:range ea:EstimationMethodCategory ;
  rdfs:comment "TENSION: the corpus offers two distinct enumerations both called '[types/classes] of reliability' -- by error source (see ErrorSourceCategory) and by estimation method (this axis). Both are modeled as separate orthogonal axes on the same ea:Reliability class." .
ea:EstimationMethodCategory a owl:Class .
ea:InterRaterEstimationValue a owl:Class ; rdfs:subClassOf ea:EstimationMethodCategory .
ea:TestRetestEstimationValue a owl:Class ; rdfs:subClassOf ea:EstimationMethodCategory .
ea:InterMethodEstimationValue a owl:Class ; rdfs:subClassOf ea:EstimationMethodCategory .
ea:InternalConsistencyEstimationValue a owl:Class ; rdfs:subClassOf ea:EstimationMethodCategory .
ea:EstimationMethodCategory owl:disjointUnionOf
  ( ea:InterRaterEstimationValue ea:TestRetestEstimationValue
    ea:InterMethodEstimationValue ea:InternalConsistencyEstimationValue ) .

ea:InterRaterReliability a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Reliability
    [ a owl:Restriction ; owl:onProperty ea:hasEstimationMethodCategory ;
      owl:someValuesFrom ea:InterRaterEstimationValue ] ) ] ;
  rdfs:comment "Degree of agreement between two or more raters." .
ea:TestRetestReliability a owl:Class ;
  skos:altLabel "repeatability" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Reliability
    [ a owl:Restriction ; owl:onProperty ea:hasEstimationMethodCategory ;
      owl:someValuesFrom ea:TestRetestEstimationValue ] ) ] ;
  rdfs:comment "Degree to which test scores are consistent from one administration to the next; includes intra-rater reliability." .
ea:IntraRaterReliability a owl:Class ; rdfs:subClassOf ea:TestRetestReliability .
ea:InterMethodReliability a owl:Class ;
  skos:altLabel "parallel-forms reliability" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Reliability
    [ a owl:Restriction ; owl:onProperty ea:hasEstimationMethodCategory ;
      owl:someValuesFrom ea:InterMethodEstimationValue ] ) ] ;
  rdfs:comment "Consistency when there is variation in methods or instruments used." .
ea:InternalConsistencyReliability a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Reliability
    [ a owl:Restriction ; owl:onProperty ea:hasEstimationMethodCategory ;
      owl:someValuesFrom ea:InternalConsistencyEstimationValue ] ) ] ;
  rdfs:comment "Consistency of results across items within a test; commonly measured by Cronbach's alpha." .

ea:ParallelFormsReliability a owl:Class ; owl:equivalentClass ea:InterMethodReliability .
ea:SplitHalfReliability a owl:Class ; rdfs:subClassOf ea:InternalConsistencyReliability ;
  rdfs:comment "Treats the two halves of a measure as alternate forms." .

#################################################################
# PROFICIENCY, COMPETENCY-BASED LEARNING, STANDARDIZED-TEST SUBTYPES
#################################################################

ea:Proficiency a owl:Class ;
  rdfs:comment "Proficiency levels, scales, and cut-off scores on standardized tests and other forms of assessment." .

ea:CompetencyBasedLearning a owl:Class ;
  skos:altLabel "proficiency-based learning", "mastery-based learning", "outcome-based learning",
    "performance-based learning", "standards-based learning" ;
  rdfs:comment "Systems of instruction, assessment, grading, and academic reporting based on students demonstrating learned knowledge and skills." .

ea:AchievementTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest ;
  rdfs:comment "Backward-looking: measures knowledge and skills already learned." .
ea:AptitudeTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest ;
  rdfs:comment "Forward-looking: attempts to predict ability to succeed in a future endeavor." .
ea:CollegeAdmissionsTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest, ea:NormReferencedTest .
ea:InternationalComparisonTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest .
ea:PsychologicalTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest .
owl:AllDisjointClasses [ owl:members
  ( ea:AchievementTest ea:AptitudeTest ea:CollegeAdmissionsTest
    ea:InternationalComparisonTest ea:PsychologicalTest ) ] .

#################################################################
# VALUE-ADDED / GROWTH / SCORE INFLATION / MEASUREMENT ERROR
#################################################################

ea:ValueAddedMeasure a owl:Class ; skos:altLabel "growth measure" ;
  rdfs:comment "Used to estimate how much effect individual teachers have on student learning, using standardized-test results." .
ea:StudentGrowthMeasure a owl:Class ;
  rdfs:comment "A related but distinct method of quantifying academic achievement and growth from ea:ValueAddedMeasure." .

ea:ScoreInflation a owl:Class ;
  rdfs:comment "Student scores increase without genuine improvement in learning." .
ea:MeasurementError a owl:Class ;
  rdfs:comment "Difference between what a test score indicates and a student's actual knowledge/abilities, or errors introduced in data collection/reporting." .
ea:TestingMeasurementError a owl:Class ; rdfs:subClassOf ea:MeasurementError .
ea:DataReportingMeasurementError a owl:Class ; rdfs:subClassOf ea:MeasurementError .
owl:AllDisjointClasses [ owl:members ( ea:TestingMeasurementError ea:DataReportingMeasurementError ) ] .

#################################################################
# TRANSFER OF LEARNING (two orthogonal axes)
#################################################################

ea:TransferOfLearning a owl:Class ;
  rdfs:comment "Application of skill, knowledge, or understanding to resolve a novel problem or situation." .

ea:hasTransferContextCategory a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:TransferOfLearning ; rdfs:range ea:TransferContextCategory .
ea:TransferContextCategory a owl:Class .
ea:NearContextValue a owl:Class ; rdfs:subClassOf ea:TransferContextCategory .
ea:FarContextValue a owl:Class ; rdfs:subClassOf ea:TransferContextCategory .
ea:TransferContextCategory owl:disjointUnionOf ( ea:NearContextValue ea:FarContextValue ) .

ea:NearTransfer a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:TransferOfLearning
    [ a owl:Restriction ; owl:onProperty ea:hasTransferContextCategory ;
      owl:someValuesFrom ea:NearContextValue ] ) ] .
ea:FarTransfer a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:TransferOfLearning
    [ a owl:Restriction ; owl:onProperty ea:hasTransferContextCategory ;
      owl:someValuesFrom ea:FarContextValue ] ) ] .

ea:hasTransferEffectCategory a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:TransferOfLearning ; rdfs:range ea:TransferEffectCategory .
ea:TransferEffectCategory a owl:Class .
ea:PositiveEffectValue a owl:Class ; rdfs:subClassOf ea:TransferEffectCategory .
ea:NegativeEffectValue a owl:Class ; rdfs:subClassOf ea:TransferEffectCategory .
ea:TransferEffectCategory owl:disjointUnionOf ( ea:PositiveEffectValue ea:NegativeEffectValue ) .

ea:PositiveTransfer a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:TransferOfLearning
    [ a owl:Restriction ; owl:onProperty ea:hasTransferEffectCategory ;
      owl:someValuesFrom ea:PositiveEffectValue ] ) ] .
ea:NegativeTransfer a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:TransferOfLearning
    [ a owl:Restriction ; owl:onProperty ea:hasTransferEffectCategory ;
      owl:someValuesFrom ea:NegativeEffectValue ] ) ] .

#################################################################
# LEARNING OUTCOMES / CONSTRUCTIVE ALIGNMENT
#################################################################

ea:LearningOutcome a owl:Class ;
  rdfs:comment "Statements about what students should be able to do by the end of a teaching session." .
ea:hasLearningOutcome a owl:ObjectProperty ; rdfs:domain ea:Assessment ; rdfs:range ea:LearningOutcome .

ea:AimLearningOutcome a owl:Class ; rdfs:subClassOf ea:LearningOutcome ;
  skos:altLabel "intended learning outcome" .
ea:ObjectiveLearningOutcome a owl:Class ; rdfs:subClassOf ea:LearningOutcome ;
  skos:altLabel "measured learning outcome" .
ea:UnintendedLearningOutcome a owl:Class ; rdfs:subClassOf ea:LearningOutcome .
ea:LearningOutcome owl:disjointUnionOf
  ( ea:AimLearningOutcome ea:ObjectiveLearningOutcome ea:UnintendedLearningOutcome ) .

ea:LearningOutcomeTaxonomy a owl:Class .
ea:BloomsTaxonomy a owl:Class ; rdfs:subClassOf ea:LearningOutcomeTaxonomy .
ea:StructureOfObservedLearningOutcome a owl:Class ; rdfs:subClassOf ea:LearningOutcomeTaxonomy ;
  skos:altLabel "SOLO" .
ea:DIKWPyramid a owl:Class ; rdfs:subClassOf ea:LearningOutcomeTaxonomy .
ea:ModelOfHierarchicalComplexity a owl:Class ; rdfs:subClassOf ea:LearningOutcomeTaxonomy .

ea:ConstructiveAlignment a owl:Class ;
  rdfs:comment "Devising teaching/learning activities and assessment tasks that directly address intended learning outcomes." .

#################################################################
# FEEDBACK
#################################################################

ea:Feedback a owl:Class .
ea:hasFeedback a owl:ObjectProperty ; rdfs:domain ea:Assessment ; rdfs:range ea:Feedback .
ea:CorrectiveFeedback a owl:Class ; rdfs:subClassOf ea:Feedback ;
  rdfs:comment "Nonevaluative, supportive, timely, specific feedback on understanding or performance." .
ea:Recast a owl:Class ; rdfs:subClassOf ea:CorrectiveFeedback .

#################################################################
# PORTFOLIO
#################################################################

ea:Portfolio a owl:Class ;
  rdfs:comment "A compilation of academic work and other educational evidence." .
ea:hasPortfolio a owl:ObjectProperty ; rdfs:domain ea:Assessment ; rdfs:range ea:Portfolio .
ea:DigitalPortfolio a owl:Class ; rdfs:subClassOf ea:Portfolio ; skos:altLabel "e-portfolio" .
ea:CapstonePortfolio a owl:Class ; rdfs:subClassOf ea:Portfolio .

#################################################################
# LEARNING TYPES (formal / non-formal / informal)
#################################################################

ea:Learning a owl:Class .
ea:FormalLearning a owl:Class ; rdfs:subClassOf ea:Learning .
ea:NonFormalLearning a owl:Class ; rdfs:subClassOf ea:Learning ;
  rdfs:comment "Organized learning outside the formal learning system." .
ea:InformalLearning a owl:Class ; rdfs:subClassOf ea:Learning ;
  rdfs:comment "Less structured than non-formal learning; occurs through day-to-day experience." .
ea:Learning owl:disjointUnionOf ( ea:FormalLearning ea:NonFormalLearning ea:InformalLearning ) .

#################################################################
# MEASUREMENT THEORY (minor supporting hierarchy)
#################################################################

ea:MeasurementTheory a owl:Class .
ea:ClassicalTestTheory a owl:Class ; rdfs:subClassOf ea:MeasurementTheory .
ea:ItemResponseTheory a owl:Class ; rdfs:subClassOf ea:MeasurementTheory .
ea:RaschModel a owl:Class ; rdfs:subClassOf ea:ItemResponseTheory .

#################################################################
# MISC TESTING PHENOMENA
#################################################################

ea:TeachingToTheTest a owl:Class ;
  rdfs:comment "Deliberately narrowing instruction to focus only on material that will be measured on the test." .
ea:TestAnxiety a owl:Class ;
  rdfs:comment "Anxiety that can appear when a person believes they are being judged by others during testing." .
ea:CheatingOnTest a owl:Class ;
  rdfs:comment "Using unauthorized means or methods to obtain a desired test score or grade." .
