@prefix ea:   <http://example.org/onto/assessment#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .

<http://example.org/onto/assessment> a owl:Ontology ;
  rdfs:comment "An ontology of educational assessment concepts derived from a corpus on educational assessment, testing, validity, reliability, grading and feedback." .

#################################################################
# TOP-LEVEL CLASSES
#################################################################

ea:Assessment a owl:Class ;
  rdfs:label "Assessment" ;
  skos:altLabel "educational evaluation" ;
  rdfs:comment "The systematic process of documenting and using empirical data on the knowledge, skill, attitudes, aptitude and beliefs of learners to refine programs and improve learning. Assessment is often used interchangeably with 'test' but is not limited to tests." .

ea:Test a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:label "Test" ;
  skos:altLabel "examination" , "exam" , "evaluation" ;
  rdfs:comment "An examination (exam) or test is an educational assessment intended to measure a test-taker's knowledge, skill, aptitude, physical fitness, or classification. Modeled as narrower than Assessment per 'assessment ... is not limited to tests'." .

ea:TestItem a owl:Class ;
  rdfs:label "TestItem" ;
  rdfs:comment "A component of a test consisting of a stem/prompt and, where applicable, answer options. 'Item' is the general term; 'question' is a misnomer since not all items are phrased as questions." .

ea:AnswerOption a owl:Class ;
  rdfs:label "AnswerOption" .

ea:Rubric a owl:Class ;
  rdfs:label "Rubric" ;
  skos:altLabel "scoring guide" ;
  rdfs:comment "A scoring guide used to evaluate the quality of students' constructed responses (Popham). Typically a table of criteria, quality definitions and a scoring strategy." .

ea:GradingMethod a owl:Class ;
  rdfs:label "GradingMethod" .

ea:Validity a owl:Class ;
  rdfs:label "Validity" ;
  rdfs:comment "The degree to which an assessment measures what it is intended to measure." .

ea:Reliability a owl:Class ;
  rdfs:label "Reliability" ;
  rdfs:comment "The consistency of an assessment; freedom of a measure from measurement error. X = T + E (observed = true + error)." .

ea:LearningOutcome a owl:Class ;
  rdfs:label "LearningOutcome" ;
  rdfs:comment "A statement about what students should be able to do by the end of a teaching session." .

ea:LearningOutcomeTaxonomy a owl:Class ;
  rdfs:label "LearningOutcomeTaxonomy" .

ea:Feedback a owl:Class ;
  rdfs:label "Feedback" .

ea:NormGroup a owl:Class ;
  rdfs:label "NormGroup" ;
  skos:altLabel "norming group" ;
  rdfs:comment "The sample drawn from a population against which test scores are compared in norm-referenced assessment." .

ea:Learning a owl:Class ;
  rdfs:label "Learning" .

ea:EducationalMeasure a owl:Class ;
  rdfs:label "EducationalMeasure" ;
  rdfs:comment "A derived statistic used to quantify teacher or student effect on learning, distinct from an Assessment itself." .

ea:MeasurementPhenomenon a owl:Class ;
  rdfs:label "MeasurementPhenomenon" .

ea:ProficiencyLevel a owl:Class ;
  rdfs:label "ProficiencyLevel" ;
  rdfs:comment "A standard or cut-off determination of whether a student has achieved expected learning." .

#################################################################
# VALUE-PARTITION (AXIS) CLASSES
#################################################################

ea:PurposeCategory a owl:Class ; rdfs:label "PurposeCategory" .
ea:PlacementPurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:FormativePurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:SummativePurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:DiagnosticPurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:PurposeCategory owl:disjointUnionOf ( ea:PlacementPurpose ea:FormativePurpose ea:SummativePurpose ea:DiagnosticPurpose ) ;
  rdfs:comment "Corpus: 'Assessment is often divided into initial, formative, and summative categories' and separately lists 'Placement, formative, summative and diagnostic assessment' as coordinate categories." .

ea:ObjectivityCategory a owl:Class ; rdfs:label "ObjectivityCategory" .
ea:ObjectiveCategory a owl:Class ; rdfs:subClassOf ea:ObjectivityCategory .
ea:SubjectiveCategory a owl:Class ; rdfs:subClassOf ea:ObjectivityCategory .
ea:ObjectivityCategory owl:disjointUnionOf ( ea:ObjectiveCategory ea:SubjectiveCategory ) .

ea:ReferencingCategory a owl:Class ; rdfs:label "ReferencingCategory" .
ea:CriterionReferencedCategory a owl:Class ; rdfs:subClassOf ea:ReferencingCategory .
ea:NormReferencedCategory a owl:Class ; rdfs:subClassOf ea:ReferencingCategory .
ea:IpsativeCategory a owl:Class ; rdfs:subClassOf ea:ReferencingCategory .
ea:ReferencingCategory owl:disjointUnionOf ( ea:CriterionReferencedCategory ea:NormReferencedCategory ea:IpsativeCategory ) ;
  rdfs:comment "Corpus numbered list (5)(6)(7): criterion-referenced, norm-referenced, ipsative, each method usable to grade the same test paper." .

ea:FormalityCategory a owl:Class ; rdfs:label "FormalityCategory" .
ea:FormalCategory a owl:Class ; rdfs:subClassOf ea:FormalityCategory .
ea:InformalCategory a owl:Class ; rdfs:subClassOf ea:FormalityCategory .
ea:FormalityCategory owl:disjointUnionOf ( ea:FormalCategory ea:InformalCategory ) .

ea:AdministrationLocusCategory a owl:Class ; rdfs:label "AdministrationLocusCategory" .
ea:InternalLocus a owl:Class ; rdfs:subClassOf ea:AdministrationLocusCategory .
ea:ExternalLocus a owl:Class ; rdfs:subClassOf ea:AdministrationLocusCategory .
ea:AdministrationLocusCategory owl:disjointUnionOf ( ea:InternalLocus ea:ExternalLocus ) .

ea:StandardizationCategory a owl:Class ; rdfs:label "StandardizationCategory" .
ea:StandardizedCategory a owl:Class ; rdfs:subClassOf ea:StandardizationCategory .
ea:NonStandardizedCategory a owl:Class ; rdfs:subClassOf ea:StandardizationCategory .
ea:StandardizationCategory owl:disjointUnionOf ( ea:StandardizedCategory ea:NonStandardizedCategory ) .

ea:StakesCategory a owl:Class ; rdfs:label "StakesCategory" .
ea:HighStakesCategory a owl:Class ; rdfs:subClassOf ea:StakesCategory .
ea:LowStakesCategory a owl:Class ; rdfs:subClassOf ea:StakesCategory .
ea:StakesCategory owl:disjointUnionOf ( ea:HighStakesCategory ea:LowStakesCategory ) .

ea:AssessorRoleCategory a owl:Class ; rdfs:label "AssessorRoleCategory" .
ea:TeacherRole a owl:Class ; rdfs:subClassOf ea:AssessorRoleCategory .
ea:PeerRole a owl:Class ; rdfs:subClassOf ea:AssessorRoleCategory .
ea:SelfRole a owl:Class ; rdfs:subClassOf ea:AssessorRoleCategory .
owl:AllDisjointClasses [ owl:members ( ea:TeacherRole ea:PeerRole ea:SelfRole ) ] .

ea:GranularityLevel a owl:Class ; rdfs:label "GranularityLevel" .
ea:LearnerGranularity a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:LearningCommunityGranularity a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:CourseGranularity a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:AcademicProgramGranularity a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:InstitutionGranularity a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:EducationalSystemGranularity a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:GranularityLevel owl:disjointUnionOf ( ea:LearnerGranularity ea:LearningCommunityGranularity ea:CourseGranularity ea:AcademicProgramGranularity ea:InstitutionGranularity ea:EducationalSystemGranularity ) ;
  rdfs:comment "Corpus: assessment can focus on the individual learner, the learning community, a course, an academic program, the institution, or the educational system as a whole (granularity)." .

ea:PerformanceFormat a owl:Class ; rdfs:label "PerformanceFormat" .
ea:AssessmentProduct a owl:Class ; rdfs:subClassOf ea:PerformanceFormat .
ea:AssessmentPerformance a owl:Class ; rdfs:subClassOf ea:PerformanceFormat .
ea:PerformanceFormat owl:disjointUnionOf ( ea:AssessmentProduct ea:AssessmentPerformance ) ;
  rdfs:comment "Corpus: 'Performance formats are further classified into products and performances.'" .

ea:TestScoreInterpretation a owl:Class ; rdfs:label "TestScoreInterpretation" .
ea:NormReferencedScoreInterpretation a owl:Class ; rdfs:subClassOf ea:TestScoreInterpretation .
ea:CriterionReferencedScoreInterpretation a owl:Class ; rdfs:subClassOf ea:TestScoreInterpretation .
ea:TestScoreInterpretation owl:disjointUnionOf ( ea:NormReferencedScoreInterpretation ea:CriterionReferencedScoreInterpretation ) ;
  rdfs:comment "Corpus: 'There are two types of test score interpretations: a norm-referenced score interpretation or a criterion-referenced score interpretation.' Distinct taxonomy from ReferencingCategory even though conceptually parallel." .

#################################################################
# OBJECT PROPERTIES (AXIS PROPERTIES)
#################################################################

ea:hasPurpose a owl:ObjectProperty , owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:PurposeCategory .

ea:hasObjectivity a owl:ObjectProperty , owl:FunctionalProperty ;
  rdfs:domain owl:Thing ; rdfs:range ea:ObjectivityCategory ;
  rdfs:comment "Applies to both ea:Assessment and ea:TestItem." .

ea:hasReferencing a owl:ObjectProperty , owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:ReferencingCategory .

ea:hasFormality a owl:ObjectProperty , owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:FormalityCategory .

ea:hasAdministrationLocus a owl:ObjectProperty , owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:AdministrationLocusCategory .

ea:hasStandardization a owl:ObjectProperty , owl:FunctionalProperty ;
  rdfs:domain ea:Test ; rdfs:range ea:StandardizationCategory .

ea:hasStakes a owl:ObjectProperty , owl:FunctionalProperty ;
  rdfs:domain ea:Test ; rdfs:range ea:StakesCategory .

ea:hasAssessorRole a owl:ObjectProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:AssessorRoleCategory .

ea:hasGranularity a owl:ObjectProperty , owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:GranularityLevel .

ea:hasPerformanceFormat a owl:ObjectProperty ;
  rdfs:domain ea:PerformanceBasedAssessment ; rdfs:range ea:PerformanceFormat .

ea:hasScoreInterpretation a owl:ObjectProperty , owl:FunctionalProperty ;
  rdfs:domain ea:Test ; rdfs:range ea:TestScoreInterpretation .

ea:hasNormGroup a owl:ObjectProperty , owl:FunctionalProperty ;
  rdfs:domain ea:NormReferencedTest ; rdfs:range ea:NormGroup .

ea:hasRubric a owl:ObjectProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:Rubric .

ea:hasItem a owl:ObjectProperty ;
  rdfs:domain ea:Test ; rdfs:range ea:TestItem .

ea:isItemOf a owl:ObjectProperty ;
  owl:inverseOf ea:hasItem ;
  rdfs:domain ea:TestItem ; rdfs:range ea:Test .

ea:hasAnswerOption a owl:ObjectProperty ;
  rdfs:domain ea:MultipleChoiceItem ; rdfs:range ea:AnswerOption .

ea:hasLearningOutcome a owl:ObjectProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:LearningOutcome .

ea:hasValidityEvidence a owl:ObjectProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:Validity .

ea:hasReliabilityEstimate a owl:ObjectProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:Reliability .

ea:hasFeedback a owl:ObjectProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:Feedback .

#################################################################
# DATATYPE PROPERTIES
#################################################################

ea:hasReliabilityCoefficient a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain ea:Reliability ; rdfs:range xsd:decimal ;
  rdfs:comment "Ranges from 0.00 (much error) to 1.00 (no error). Rx = Vt/Vx." .

ea:hasObservedScore a owl:DatatypeProperty ; rdfs:domain ea:Assessment ; rdfs:range xsd:decimal .
ea:hasTrueScore a owl:DatatypeProperty ; rdfs:domain ea:Assessment ; rdfs:range xsd:decimal .
ea:hasErrorScore a owl:DatatypeProperty ; rdfs:domain ea:Assessment ; rdfs:range xsd:decimal .
ea:hasItemCount a owl:DatatypeProperty ; rdfs:domain ea:Test ; rdfs:range xsd:integer .
ea:hasCutScore a owl:DatatypeProperty ; rdfs:domain ea:CriterionReferencedTest ; rdfs:range xsd:decimal ;
  rdfs:comment "The minimum score required to pass a mastery test; the cutscore is not the criterion itself." .
ea:hasCriterionDescription a owl:DatatypeProperty ; rdfs:domain ea:CriterionReferencedTest ; rdfs:range xsd:string .
ea:hasStem a owl:DatatypeProperty ; rdfs:domain ea:MultipleChoiceItem ; rdfs:range xsd:string .
ea:hasPointValue a owl:DatatypeProperty ; rdfs:domain ea:Assessment ; rdfs:range xsd:decimal .

#################################################################
# ASSESSMENT PURPOSE/TIMING BRIDGE CLASSES
#################################################################

ea:PlacementAssessment a owl:Class ;
  rdfs:label "PlacementAssessment" ;
  skos:altLabel "pre-assessment" , "initial assessment" , "threshold knowledge test" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:PlacementPurpose ] ) ] ;
  rdfs:comment "Used to place students at the most appropriate point in an instructional sequence based on prior achievement; conducted before instruction; generally not graded." .

ea:FormativeAssessment a owl:Class ;
  rdfs:label "FormativeAssessment" ;
  skos:altLabel "educative assessment" , "assessment for learning" , "classroom assessment" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:FormativePurpose ] ) ] ;
  rdfs:comment "Carried out during the learning process to modify teaching and learning activities; not necessarily graded. 'When the cook tastes the soup, that's formative.' (Stake/Black)." .

ea:SummativeAssessment a owl:Class ;
  rdfs:label "SummativeAssessment" ;
  skos:altLabel "assessment of learning" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:SummativePurpose ] ) ] ;
  rdfs:comment "Carried out at the end of a course or project; typically graded. 'When the guests taste the soup, that's summative.'" .

ea:DiagnosticAssessment a owl:Class ;
  rdfs:label "DiagnosticAssessment" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:DiagnosticPurpose ] ) ] ;
  rdfs:subClassOf ea:FormativeAssessment ;
  rdfs:comment "TENSION: one passage lists Placement/Formative/Summative/Diagnostic as four coordinate, mutually exclusive categories (encoded via the disjoint PurposeCategory partition), while another passage states 'A common form of formative assessment is diagnostic assessment', here encoded as rdfs:subClassOf ea:FormativeAssessment. Both axioms are retained even though, combined with the functional, disjoint hasPurpose partition, they are formally in tension." .

ea:SelfAssessment a owl:Class ;
  rdfs:label "SelfAssessment" ;
  rdfs:subClassOf ea:DiagnosticAssessment ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasAssessorRole ; owl:someValuesFrom ea:SelfRole ] ) ] ;
  rdfs:comment "'Self-assessment is a form of diagnostic assessment in which students assess themselves.'" .

ea:ForwardLookingAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Asks those being assessed to consider themselves in hypothetical future situations." .

#################################################################
# OBJECTIVITY BRIDGE CLASSES
#################################################################

ea:ObjectiveAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasObjectivity ; owl:someValuesFrom ea:ObjectiveCategory ] ) ] ;
  rdfs:comment "A form of questioning that has a single correct answer." .

ea:SubjectiveAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasObjectivity ; owl:someValuesFrom ea:SubjectiveCategory ] ) ] ;
  rdfs:comment "A form of questioning that may have more than one correct answer." .

ea:ObjectiveItem a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:TestItem
    [ a owl:Restriction ; owl:onProperty ea:hasObjectivity ; owl:someValuesFrom ea:ObjectiveCategory ] ) ] .

ea:SubjectiveItem a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:TestItem
    [ a owl:Restriction ; owl:onProperty ea:hasObjectivity ; owl:someValuesFrom ea:SubjectiveCategory ] ) ] .

#################################################################
# REFERENCING BRIDGE CLASSES (ASSESSMENT LEVEL)
#################################################################

ea:CriterionReferencedAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:CriterionReferencedCategory ] ) ] ;
  rdfs:comment "Candidates are measured against defined, objective criteria (e.g., a driving test)." .

ea:NormReferencedAssessment a owl:Class ;
  skos:altLabel "normative assessment" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:NormReferencedCategory ] ) ] ;
  rdfs:comment "Relative to the student body taking it; a way of comparing students (e.g., IQ test)." .

ea:IpsativeAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:IpsativeCategory ] ) ] ;
  rdfs:comment "Self-comparison either in the same domain over time, or comparative to other domains within the same student." .

#################################################################
# FORMALITY / LOCUS BRIDGE CLASSES
#################################################################

ea:FormalAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasFormality ; owl:someValuesFrom ea:FormalCategory ] ) ] ;
  rdfs:comment "Usually implies a written document, given a numerical score or grade." .

ea:InformalAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasFormality ; owl:someValuesFrom ea:InformalCategory ] ) ] ;
  rdfs:comment "Does not contribute to a student's final grade; e.g. observation, checklists, rubrics." .

ea:InternalAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasAdministrationLocus ; owl:someValuesFrom ea:InternalLocus ] ) ] ;
  rdfs:comment "Set and marked by the school." .

ea:ExternalAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasAdministrationLocus ; owl:someValuesFrom ea:ExternalLocus ] ) ] ;
  rdfs:comment "Set by the governing body and marked by unbiased personnel." .

#################################################################
# STANDARDIZATION / STAKES BRIDGE CLASSES (TEST LEVEL)
#################################################################

ea:StandardizedTest a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
    [ a owl:Restriction ; owl:onProperty ea:hasStandardization ; owl:someValuesFrom ea:StandardizedCategory ] ) ] ;
  rdfs:comment "Administered and scored in a consistent or standard manner for all test takers." .

ea:NonStandardizedTest a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
    [ a owl:Restriction ; owl:onProperty ea:hasStandardization ; owl:someValuesFrom ea:NonStandardizedCategory ] ) ] ;
  rdfs:comment "Significantly different tests given to different test takers, or same test under significantly different conditions/grading." .

ea:HighStakesTest a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
    [ a owl:Restriction ; owl:onProperty ea:hasStakes ; owl:someValuesFrom ea:HighStakesCategory ] ) ] ;
  rdfs:comment "A test with a desired reward for good performance, or used to make important decisions about students, educators, schools, or districts." .

ea:LowStakesTest a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
    [ a owl:Restriction ; owl:onProperty ea:hasStakes ; owl:someValuesFrom ea:LowStakesCategory ] ) ] .

ea:NormReferencedTest a owl:Class ;
  skos:altLabel "NRT" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
    [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:NormReferencedCategory ] ) ] ;
  rdfs:comment "Yields an estimate of the position of the tested individual in a predefined population." .

ea:CriterionReferencedTest a owl:Class ;
  skos:altLabel "CRT" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
    [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:CriterionReferencedCategory ] ) ] ;
  rdfs:comment "Uses test scores to show how well test takers performed on a given task, not relative to other test takers." .

ea:MasteryTest a owl:Class ;
  rdfs:subClassOf ea:CriterionReferencedTest ;
  rdfs:comment "A criterion-referenced test with a cutscore where the examinee passes if the score exceeds the cutscore." .

ea:CompetitiveExamination a owl:Class ;
  rdfs:label "CompetitiveExamination" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
    [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:NormReferencedCategory ]
    [ a owl:Restriction ; owl:onProperty ea:hasStakes ; owl:someValuesFrom ea:HighStakesCategory ] ) ] ;
  rdfs:comment "Norm-referenced, high-stakes tests in which candidates are ranked and top rankers selected." .

#################################################################
# TEST FORMAT / MODALITY SUBCLASSES
#################################################################

ea:WrittenTest a owl:Class ; rdfs:subClassOf ea:Test .
ea:OralTest a owl:Class ; rdfs:subClassOf ea:Test .
ea:PracticalTest a owl:Class ; rdfs:subClassOf ea:Test .
ea:ComputerBasedTest a owl:Class ; rdfs:subClassOf ea:Test ; skos:altLabel "on-screen test" , "eExam" .

ea:PerformanceTest a owl:Class ;
  rdfs:subClassOf ea:Test ;
  rdfs:comment "An assessment that requires an examinee to actually perform a task or activity, rather than simply answering questions, to ensure greater fidelity to what is being tested (e.g. behind-the-wheel driving test)." .

ea:Quiz a owl:Class ;
  rdfs:subClassOf ea:Test ;
  rdfs:comment "A brief assessment covering a small amount of material; usually a formative assessment of low point value." .

ea:MidtermExamination a owl:Class ;
  rdfs:subClassOf ea:Test ;
  rdfs:comment "An exam given near the middle of an academic grading term; a type of formative or summative assessment." .
ea:MidtermExamination rdfs:subClassOf ea:FormativeAssessment , ea:SummativeAssessment .

ea:FinalExamination a owl:Class ;
  rdfs:subClassOf ea:Test , ea:SummativeAssessment ;
  rdfs:comment "A review and assessment of each student's knowledge at the end of a course; a greater form of a unit test." .

#################################################################
# PERFORMANCE-BASED / AUTHENTIC / PORTFOLIO / CONTINUOUS / COMPLEX
#################################################################

ea:PerformanceBasedAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Similar to summative assessment in focusing on achievement; a well-defined task is identified and students create, produce, or do something, often with real-world application." .

ea:AuthenticAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  owl:equivalentClass ea:PerformanceBasedAssessment ;
  rdfs:comment "'The measurement of accomplishments within a realistic, practical context that is relevant outside of the school setting.' Corpus states performance assessments 'may also be called authentic assessments' -- modeled here as equivalent, though each is independently defined by genus+differentia in the corpus." .

ea:Portfolio a owl:Class ;
  rdfs:comment "A compilation of academic work and other educational evidence assembled over time." .

ea:PortfolioAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Assessment based on review of a student portfolio; may be used both formatively and summatively." .
ea:PortfolioAssessment rdfs:subClassOf ea:FormativeAssessment , ea:SummativeAssessment .

ea:hasEvidence a owl:ObjectProperty ;
  rdfs:domain ea:PortfolioAssessment ; rdfs:range ea:Portfolio .

ea:ContinuousAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Evaluates a student's progress throughout a prescribed course; often includes formative assessment; alternative to the final examination system." .

ea:ComplexAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:comment "An assessment that requires a rubric and an expert examiner (e.g. thesis, funding proposal)." .

#################################################################
# TEST ITEM TAXONOMY
#################################################################

ea:MultipleChoiceItem a owl:Class ;
  rdfs:subClassOf ea:TestItem , ea:ObjectiveItem ;
  skos:altLabel "MCQ" , "multiple choice question" ;
  rdfs:comment "Consists of a stem and several alternative answers (options); one option is the key, the rest are distractors." .

ea:TrueFalseItem a owl:Class ; rdfs:subClassOf ea:TestItem , ea:ObjectiveItem .
ea:MatchingItem a owl:Class ; rdfs:subClassOf ea:TestItem , ea:ObjectiveItem .
ea:MultipleResponseItem a owl:Class ;
  rdfs:subClassOf ea:TestItem , ea:ObjectiveItem ;
  rdfs:comment "More than one answer may be keyed as correct, in contrast to single-answer multiple-choice items." .

ea:FillInTheBlankItem a owl:Class ;
  rdfs:subClassOf ea:TestItem ;
  rdfs:comment "Provides a test taker with identifying characteristics and requires recall of the correct term, optionally from a word bank." .

ea:ShortAnswerItem a owl:Class ; rdfs:subClassOf ea:TestItem , ea:SubjectiveItem .

ea:EssayItem a owl:Class ;
  rdfs:subClassOf ea:TestItem , ea:SubjectiveItem ;
  skos:altLabel "free response question" , "FRQ" , "extended-response item" ;
  rdfs:comment "An open-ended question requiring a prose response, graded for factual correctness and potentially persuasiveness and style." .

ea:Key a owl:Class ; rdfs:subClassOf ea:AnswerOption .
ea:Distractor a owl:Class ; rdfs:subClassOf ea:AnswerOption .
ea:AnswerOption owl:disjointUnionOf ( ea:Key ea:Distractor ) .

ea:TrueFalseFamilyItem a owl:Class ;
  rdfs:subClassOf ea:MultipleChoiceItem ;
  rdfs:comment "First family of multiple-choice questions, requiring the test taker to choose all appropriate answers. Note: distinct sense of 'true/false' from ea:TrueFalseItem used in the objective/subjective item list -- corpus uses the phrase in two different ways." .

ea:OneBestAnswerFamilyItem a owl:Class ;
  rdfs:subClassOf ea:MultipleChoiceItem ;
  rdfs:comment "Second family of multiple-choice questions, requiring the test taker to answer only one from a list of answers." .
ea:MultipleChoiceItem owl:disjointUnionOf ( ea:TrueFalseFamilyItem ea:OneBestAnswerFamilyItem ) .

#################################################################
# VALIDITY TAXONOMY
#################################################################

ea:ContentValidity a owl:Class ;
  rdfs:subClassOf ea:Validity ;
  skos:altLabel "logical validity" ;
  rdfs:comment "The systematic examination of the test content to determine whether it covers a representative sample of the behavior domain to be measured." .

ea:CriterionValidity a owl:Class ;
  rdfs:subClassOf ea:Validity ;
  skos:altLabel "criterion-related validity" ;
  rdfs:comment "The extent to which an operationalization correlates with, or predicts, a theoretically related outcome (the criterion)." .

ea:ConcurrentValidity a owl:Class ; rdfs:subClassOf ea:CriterionValidity .
ea:PredictiveValidity a owl:Class ; rdfs:subClassOf ea:CriterionValidity .
owl:AllDisjointClasses [ owl:members ( ea:ConcurrentValidity ea:PredictiveValidity ) ] .

ea:ConstructValidity a owl:Class ;
  rdfs:subClassOf ea:Validity ;
  rdfs:comment "The extent to which operationalizations of a construct measure the construct as defined by theory." .

ea:ConvergentValidity a owl:Class ; rdfs:subClassOf ea:ConstructValidity .
ea:DiscriminantValidity a owl:Class ; rdfs:subClassOf ea:ConstructValidity ; skos:altLabel "divergent validity" .
owl:AllDisjointClasses [ owl:members ( ea:ConvergentValidity ea:DiscriminantValidity ) ] .

ea:FaceValidity a owl:Class ;
  rdfs:subClassOf ea:Validity ;
  rdfs:comment "Whether a test appears, on its face, to measure what it purports to measure." .

ea:ConsequentialValidity a owl:Class ; rdfs:subClassOf ea:Validity .

ea:SubjectMatterValidity a owl:Class ;
  rdfs:subClassOf ea:Validity ;
  rdfs:comment "Widely used in education: predicts the score a student would get on a similar test with different questions; contrasted in the corpus with 'predictive' validity used in the workplace." .

owl:AllDisjointClasses [ owl:members ( ea:ContentValidity ea:CriterionValidity ea:ConstructValidity ea:FaceValidity ea:ConsequentialValidity ) ] ;
  rdfs:comment "Corpus lists content, criterion, construct validity as coordinate evidence categories, with 'others' being consequential and face validity." .

ea:ContentValidity rdfs:subClassOf ea:ConstructValidity .
ea:CriterionValidity rdfs:subClassOf ea:ConstructValidity .
ea:FaceValidity rdfs:subClassOf ea:ConstructValidity .
ea:ConstructValidity rdfs:comment "TENSION: one passage presents Content, Criterion, Construct (and Consequential, Face) validity as coordinate categories of validity evidence (see AllDisjointClasses above), while modern validity theory per the corpus states 'Construct validity ... subsumes all other types of validity' and is 'the overarching concern of validity research'. Both the coordinate-disjointness axiom and the subsumption axioms (rdfs:subClassOf ea:ConstructValidity) are retained, producing a deliberate tension." .

#################################################################
# RELIABILITY TAXONOMY (TWO ORTHOGONAL / OVERLAPPING TAXONOMIES)
#################################################################

ea:InterRaterReliability a owl:Class ; rdfs:subClassOf ea:Reliability ;
  rdfs:comment "Degree of agreement between two or more raters in their appraisals." .

ea:TestRetestReliability a owl:Class ; rdfs:subClassOf ea:Reliability ;
  skos:altLabel "repeatability" ;
  rdfs:comment "Degree to which test scores are consistent from one administration to the next, gathered from a single rater using the same instrument/conditions." .

ea:IntraRaterReliability a owl:Class ; rdfs:subClassOf ea:TestRetestReliability .

ea:ParallelFormsReliability a owl:Class ; rdfs:subClassOf ea:Reliability ;
  skos:altLabel "inter-method reliability" , "form equivalence" ;
  rdfs:comment "Degree to which test scores are consistent when there is variation in the methods or instruments (alternate forms) used." .

ea:InternalConsistencyReliability a owl:Class ; rdfs:subClassOf ea:Reliability ;
  rdfs:comment "Consistency of results across items within a test; commonly measured with Cronbach's alpha." .

ea:SplitHalfReliability a owl:Class ; rdfs:subClassOf ea:InternalConsistencyReliability ;
  rdfs:comment "Treats the two halves of a measure as alternate forms; stepped up to full-test length via the Spearman-Brown formula." .

owl:AllDisjointClasses [ owl:members ( ea:InterRaterReliability ea:TestRetestReliability ea:ParallelFormsReliability ea:InternalConsistencyReliability ) ] ;
  rdfs:comment "'Several general classes of reliability estimates.'" .

ea:StudentRelatedReliability a owl:Class ; rdfs:subClassOf ea:Reliability .
ea:RaterRelatedReliability a owl:Class ; rdfs:subClassOf ea:Reliability .
ea:TestAdministrationRelatedReliability a owl:Class ; rdfs:subClassOf ea:Reliability .
ea:TestRelatedReliability a owl:Class ; rdfs:subClassOf ea:Reliability .
ea:Reliability owl:disjointUnionOf ( ea:StudentRelatedReliability ea:RaterRelatedReliability ea:TestAdministrationRelatedReliability ea:TestRelatedReliability ) ;
  rdfs:comment "TENSION: the corpus names 'four types of reliability' (student-related, rater-related, test administration-related, test-related) as an exhaustive partition of ea:Reliability, which is a DIFFERENT taxonomy from the 'several general classes of reliability estimates' (inter-rater, test-retest, inter-method/parallel-forms, internal consistency) declared above via AllDisjointClasses. Both taxonomies are retained on the same ea:Reliability class, even though their relationship is not reconciled in the corpus." .

#################################################################
# GRADING / RUBRIC TAXONOMY
#################################################################

ea:HolisticGrading a owl:Class ;
  rdfs:subClassOf ea:GradingMethod ;
  skos:altLabel "nonreductionist grading" , "holistic scoring" ;
  rdfs:comment "Bases a grade on a paper's overall quality, treating the composition as a whole." .

ea:AnalyticGrading a owl:Class ;
  rdfs:subClassOf ea:GradingMethod ;
  rdfs:comment "Takes more factors into account, judging criterion-by-criterion, contrasted with holistic grading." .
ea:HolisticGrading owl:disjointWith ea:AnalyticGrading .

ea:TraitInformedScoring a owl:Class ;
  rdfs:subClassOf ea:HolisticGrading ;
  rdfs:comment "Trains raters to score to a rubric/checklist of criteria, while 'remaining holistic at heart', though it 'comes close to' analytic scoring methods." .

ea:HolisticRubric a owl:Class ;
  rdfs:subClassOf ea:Rubric ;
  rdfs:comment "Provides an overall rating for a piece of work, considering all aspects." .

ea:AnalyticRubric a owl:Class ;
  rdfs:subClassOf ea:Rubric ;
  rdfs:comment "Evaluates various dimensions or components separately." .

ea:DevelopmentalRubric a owl:Class ;
  rdfs:subClassOf ea:AnalyticRubric ;
  rdfs:comment "A subset of analytical rubrics facilitating assessment, instructional design and transformative learning through multiple dimensions of developmental succession." .

ea:Rubric owl:disjointUnionOf ( ea:HolisticRubric ea:AnalyticRubric ea:DevelopmentalRubric ) ;
  rdfs:comment "TENSION: the corpus states 'Rubrics can be classified as holistic, analytic, or developmental' (a coordinate, exhaustive three-way partition, encoded via disjointUnionOf) while ALSO stating 'Developmental rubrics [are] a subset of analytical rubrics' (encoded via ea:DevelopmentalRubric rdfs:subClassOf ea:AnalyticRubric above). Both axioms are retained even though jointly they are formally inconsistent (a disjointUnionOf member cannot also be a non-trivial subclass of a sibling member)." .

#################################################################
# LEARNING OUTCOME TAXONOMY
#################################################################

ea:AimLearningOutcome a owl:Class ; rdfs:subClassOf ea:LearningOutcome ;
  rdfs:comment "Intended learning outcome, equated with course 'aims'." .
ea:ObjectiveLearningOutcome a owl:Class ; rdfs:subClassOf ea:LearningOutcome ;
  rdfs:comment "Measured learning outcome, equated with course 'objectives'." .
ea:UnintendedLearningOutcome a owl:Class ; rdfs:subClassOf ea:LearningOutcome ;
  rdfs:comment "Beneficial outcomes that were neither planned nor sought but are simply observed." .
ea:LearningOutcome owl:disjointUnionOf ( ea:AimLearningOutcome ea:ObjectiveLearningOutcome ea:UnintendedLearningOutcome ) .

ea:BloomsTaxonomy a owl:Class ; rdfs:subClassOf ea:LearningOutcomeTaxonomy .
ea:StructureOfObservedLearningOutcome a owl:Class ; rdfs:subClassOf ea:LearningOutcomeTaxonomy ; skos:altLabel "SOLO" .
ea:DIKWPyramid a owl:Class ; rdfs:subClassOf ea:LearningOutcomeTaxonomy .
ea:ModelOfHierarchicalComplexity a owl:Class ; rdfs:subClassOf ea:LearningOutcomeTaxonomy .

#################################################################
# LEARNING TYPE TAXONOMY
#################################################################

ea:FormalLearning a owl:Class ; rdfs:subClassOf ea:Learning .
ea:NonFormalLearning a owl:Class ; rdfs:subClassOf ea:Learning ;
  rdfs:comment "Organized learning outside the formal learning system, e.g. clubs, youth organizations, workshops." .
ea:InformalLearning a owl:Class ; rdfs:subClassOf ea:Learning ;
  rdfs:comment "Less structured than non-formal learning; occurs through day-to-day experience; typically does not lead to accreditation." .
ea:Learning owl:disjointUnionOf ( ea:FormalLearning ea:NonFormalLearning ea:InformalLearning ) .

ea:CompetencyBasedLearning a owl:Class ;
  rdfs:subClassOf ea:Learning ;
  skos:altLabel "proficiency-based learning" , "mastery-based learning" , "outcome-based learning" , "performance-based learning" , "standards-based learning" ;
  rdfs:comment "Systems of instruction, assessment, grading and reporting based on students demonstrating learned knowledge/skills before progressing." .

#################################################################
# FEEDBACK TAXONOMY
#################################################################

ea:CorrectiveFeedback a owl:Class ;
  rdfs:subClassOf ea:Feedback ;
  rdfs:comment "Nonevaluative, supportive, timely, and specific feedback on understanding or performance." .

ea:Recast a owl:Class ;
  rdfs:subClassOf ea:CorrectiveFeedback ;
  rdfs:comment "A subtle correction of a young child's spoken errors, as in motherese." .

ea:FormativeFeedback a owl:Class ; rdfs:subClassOf ea:Feedback .
ea:SummativeFeedback a owl:Class ; rdfs:subClassOf ea:Feedback .
owl:AllDisjointClasses [ owl:members ( ea:FormativeFeedback ea:SummativeFeedback ) ] .

#################################################################
