#################################################################

ea:ScoreInflation a owl:Class ;
  rdfs:subClassOf ea:MeasurementPhenomenon ;
  rdfs:comment "Increase in scores that does not reflect genuine learning improvement." .

ea:MeasurementError a owl:Class ;
  rdfs:subClassOf ea:MeasurementPhenomenon ;
  rdfs:comment "Difference between what a test score indicates and a student's actual knowledge/abilities, or errors in data collection/reporting." .

ea:ValueAddedMeasure a owl:Class ;
  rdfs:subClassOf ea:EducationalMeasure ;
  skos:altLabel "growth measure" ;
  rdfs:comment "Used to estimate how much effect individual teachers have on student learning during a school year, using statistical algorithms and standardized-test results." .

ea:StudentGrowthMeasure a owl:Class ;
  rdfs:subClassOf ea:EducationalMeasure ;
  rdfs:comment "A related but distinct method of using test scores to quantify academic achievement and growth, also usable in teacher evaluation." .

#################################################################
# ADDITIONAL DISJOINTNESS: MUTUALLY EXCLUSIVE TOP ASSESSMENT KINDS
#################################################################

owl:AllDisjointClasses [ owl:members ( ea:PlacementAssessment ea:SummativeAssessment ) ] ;
